function sync(){for(let key of ['card','power','gem']){let el=$('#o-'+key);el.classList.toggle('done',state[key]);el.querySelector('i').textContent=state[key]?'✓':'○'}$('#smokes').textContent=state.smokes;$('#decoys').textContent=state.decoys;$('#loot').innerHTML=`${state.loot} <span>/ 3</span>`;$('#smoke').disabled=!state.smokes;$('#decoy').disabled=!state.decoys;$('#phase-label').textContent=state.phase==='run'?'潜入进行中':'策划阶段';$('#phase-desc').textContent=state.phase==='run'?'保持安静 · 留意守卫的视线':'时间暂停 · 规划你的完美路线';$('#start').innerHTML=state.phase==='run'?'暂停策划 <span>SPACE</span>':state.time?'继续行动 <span>SPACE</span>':'开始潜入 <span>SPACE</span>';$('#difficulty').disabled=state.time>0||state.phase==='run'}
function toggle(){if(['won','lost'].includes(state.phase))return;state.phase=state.phase==='run'?'plan':'run';sync();beep(500);say(state.phase==='run'?'行动开始。靠近目标后按 E 交互。':'行动已暂停。可以修改路线和观察巡逻位置。')}
