function showModal(html){$('#modal-content').innerHTML=html;$('#modal').classList.remove('hidden')}function finish(win){state.phase=win?'won':'lost';const score=win?Math.max(0,Math.round(1500+state.loot*300-state.time*2-state.peak*4-state.used*60)):0;let best=0;try{best=Number(localStorage.getItem('midnight-paws-best')||0);if(score>best)localStorage.setItem('midnight-paws-best',String(score))}catch{}$('#o-exit').classList.toggle('done',win);$('#o-exit i').textContent=win?'✓':'○';showModal(`<div class="eyebrow">${win?'MISSION COMPLETE':'MISSION COMPROMISED'}</div><h2>${win?'月光，现在属于你。':'糟糕，被发现了。'}</h2><p>${win?'黑芝麻轻巧地消失在夜色里。博物馆少了一颗宝石，城市多了一个传说。':'警报响彻了展厅。试着避开守卫的锥形视野，借助展台遮挡，或用烟雾弹争取时间。'}</p><div class="result-stats"><div>行动评分<b>${score}</b></div><div>耗时<b>${Math.round(state.time)}s</b></div><div>额外战利品<b>${state.loot}/3</b></div></div><p>${win?(state.peak<10?'评级：无声魅影 ✦ ✦ ✦':state.peak<50?'评级：午夜大盗 ✦ ✦':'评级：险中求胜 ✦'):'路线可以更聪明，每一次行动都是新的机会。'}</p><button class="primary" id="retry">再来一次</button>`);$('#retry').onclick=reset;beep(win?900:120,.6)}
function reset(){state={phase:'plan',time:0,alert:0,card:false,power:false,gem:false,loot:0,smokes:2,decoys:3,smokeUntil:0,decoyUntil:0,decoyPos:null,vision:state.vision,used:0,peak:0};cat.position.set(0,0,4.8);cat.rotation.y=0;if(carriedGem){cat.remove(carriedGem);carriedGem=null;}path=[];pathIndex=0;card.visible=gem.visible=glass.visible=true;gemLight.intensity=5;terminal.material=mat(0x91dfc0,{emissive:0x399d75,emissiveIntensity:.7});treasures.forEach(m=>m.visible=true);guards.forEach((g,i)=>{g.g.position.set(i===0?-4:i===1?4:0,0,i===2?1:0);g.index=0});$('#modal').classList.add('hidden');$('#o-exit').classList.remove('done');$('#o-exit i').textContent='○';$('#difficulty').disabled=false;sync();drawRoute();say('全新行动。点击地面规划路线，按空格开始。')}
function help(){if(state.phase==='run'){state.phase='plan';sync()}showModal('<div class="eyebrow">THE PERFECT HEIST</div><h2>一只猫，一场完美盗窃。</h2><p>点击地面设置行动路线，按空格开始。进入行动后，小猫会自动沿路线移动；WASD / 方向键可立即接管。</p><ul><li>靠近金色标签目标，按 E：门禁卡 → 安保终端 → 宝石 → 撤离点。</li><li>守卫的橙色扇形是视野，展台和墙体可以遮挡。暴露到 100% 就会被捕。</li><li>Shift 慢行能降低脚步声与被发现的速度。</li><li>1 烟雾弹：隐身 5 秒；2 发条老鼠：吸引守卫 6 秒。</li><li>3 切换安保视野；红色激光会周期闪烁，切断电源后永久关闭。</li><li>沿路收集 3 颗金色小宝石，低暴露、少用道具、快速撤离可提高评分。</li><li>随时按空格暂停策划；触屏点击地面移动，靠近目标会出现交互按钮。</li></ul><button class="primary" id="understood">计划好了</button>');$('#understood').onclick=()=>$('#modal').classList.add('hidden')}
$('#help').onclick=help;$('#close-modal').onclick=()=>$('#modal').classList.add('hidden');$('#start').onclick=toggle;$('#reset').onclick=reset;$('#smoke').onclick=()=>gadget('smoke');$('#decoy').onclick=()=>gadget('decoy');$('#vision').onclick=()=>{state.vision=!state.vision;$('#vision-state').textContent=state.vision?'开':'关'};$('#clear').onclick=()=>{path=[];pathIndex=0;drawRoute()};$('#undo').onclick=()=>{path.pop();pathIndex=Math.min(pathIndex,path.length);drawRoute()};$('#view').onclick=()=>{topView=!topView};$('#sound').onclick=()=>{muted=!muted;$('#sound').textContent=muted?'♪ 静音':'♪ 音效';beep()};
window.addEventListener('keydown',e=>{if(['INPUT','SELECT'].includes(e.target.tagName))return;if(e.target.tagName==='BUTTON'&&e.code==='Space')e.preventDefault();if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();keys[e.code]=true;if(e.repeat||!$('#modal').classList.contains('hidden'))return;if(e.code==='Space')toggle();if(e.code==='KeyE')interact();if(e.code==='Digit1')gadget('smoke');if(e.code==='Digit2')gadget('decoy');if(e.code==='Digit3')$('#vision').click();if(e.code==='Escape'){state.phase==='run'&&toggle()}});window.addEventListener('keyup',e=>keys[e.code]=false);window.addEventListener('blur',()=>{keys={}});
let down=null,drag=false;const ray=new T.Raycaster(),plane=new T.Plane(new T.Vector3(0,1,0),0);renderer.domElement.addEventListener('pointerdown',e=>{down={x:e.clientX,y:e.clientY};drag=false;renderer.domElement.setPointerCapture(e.pointerId)});renderer.domElement.addEventListener('pointermove',e=>{if(!down)return;let dx=e.clientX-down.x,dy=e.clientY-down.y;if(Math.abs(dx)+Math.abs(dy)>5||drag){drag=true;angle-=dx*.006;elevation=Math.max(.4,Math.min(1.3,elevation+dy*.003));down={x:e.clientX,y:e.clientY}}});renderer.domElement.addEventListener('pointerup',e=>{if(!drag&&!['won','lost'].includes(state.phase)){const r=renderer.domElement.getBoundingClientRect();ray.setFromCamera(new T.Vector2((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1),camera);const p=new T.Vector3();if(ray.ray.intersectPlane(plane,p)){if(blocked(p.x,p.z))say('这个位置有障碍，请选择展厅内的空地。');else if(state.phase==='run'){path=[{x:p.x,z:p.z}];pathIndex=0;drawRoute()}else if(path.length<24){path.push({x:p.x,z:p.z});drawRoute();beep(330,.035)}else say('路线最多支持 24 个节点。')}}down=null});renderer.domElement.addEventListener('wheel',e=>{e.preventDefault();zoom=Math.max(15,Math.min(36,zoom+e.deltaY*.015))},{passive:false});
const interactBtn=document.createElement('button');interactBtn.textContent='E · 交互';interactBtn.style.cssText='position:absolute;right:20px;bottom:138px;padding:13px 20px;background:#e8c780;color:#20382b;border:0;font-weight:bold;z-index:3';interactBtn.hidden=true;viewport.append(interactBtn);interactBtn.onclick=interact;
function resize(){const r=viewport.getBoundingClientRect();renderer.setSize(r.width,r.height);camera.aspect=r.width/r.height;camera.updateProjectionMatrix()}new ResizeObserver(resize).observe(viewport);
let last=performance.now();function tick(now){requestAnimationFrame(tick);const dt=Math.min((now-last)/1000,.05);last=now;const target=new T.Vector3(0,0,0);camera.position.set(Math.sin(angle)*zoom*Math.cos(topView?1.48:elevation),Math.sin(topView?1.48:elevation)*zoom,Math.cos(angle)*zoom*Math.cos(topView?1.48:elevation));camera.lookAt(target);gem.rotation.y+=dt*.8;gem.position.y=1.48+Math.sin(now*.0017)*.08;treasures.forEach(m=>m.rotation.y+=dt);catRing.rotation.z+=dt*.2;
if(state.phase==='run'){state.time+=dt;const difficulty=$('#difficulty').value,mult=difficulty==='easy'?.7:difficulty==='hard'?1.35:1;let dir=new T.Vector3((keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0),0,(keys.KeyS||keys.ArrowDown?1:0)-(keys.KeyW||keys.ArrowUp?1:0));if(dir.lengthSq()){dir.applyAxisAngle(new T.Vector3(0,1,0),angle);path=[];pathIndex=0;if(routeGroup.children.length)drawRoute()}else if(path[pathIndex]){dir.set(path[pathIndex].x-cat.position.x,0,path[pathIndex].z-cat.position.z);if(dir.length()<.17){pathIndex++;dir.set(0,0,0);drawRoute()}}const moving=dir.lengthSq()>.001;if(moving){dir.normalize();const speed=(keys.ShiftLeft||keys.ShiftRight?1:2)*dt;let nx=cat.position.x+dir.x*speed,nz=cat.position.z+dir.z*speed;if(!blocked(nx,cat.position.z))cat.position.x=nx;if(!blocked(cat.position.x,nz))cat.position.z=nz;cat.rotation.y=Math.atan2(-dir.x,-dir.z);cat.position.y=Math.abs(Math.sin(now*.011))*.04}else cat.position.y=0;
let seen=false;guards.forEach((g,i)=>{let dest=state.time<state.decoyUntil?state.decoyPos:new T.Vector3(g.route[g.index][0],0,g.route[g.index][1]);const delta=dest.clone().sub(g.g.position);delta.y=0;if(delta.length()<.25){if(state.time>=state.decoyUntil)g.index=(g.index+1)%g.route.length}else{delta.normalize();let step=.64*mult*dt;const gx=g.g.position.x+delta.x*step,gz=g.g.position.z+delta.z*step;if(!blocked(gx,g.g.position.z))g.g.position.x=gx;if(!blocked(g.g.position.x,gz))g.g.position.z=gz;g.heading=Math.atan2(-delta.x,-delta.z);g.g.rotation.y=g.heading}const to=cat.position.clone().sub(g.g.position);to.y=0;const dist=to.length(),forward=new T.Vector3(-Math.sin(g.heading),0,-Math.cos(g.heading));const visible=dist<3.15&&forward.dot(to.normalize())>Math.cos(.56)&&canSee(g.g.position,cat.position);const noisy=moving&&!keys.ShiftLeft&&!keys.ShiftRight&&dist<1.05;if((visible||noisy)&&state.time>=state.smokeUntil)seen=true;g.cone.material.opacity=(visible?.3:.13);g.cone.visible=state.vision});const laserOn=!state.power&&Math.sin(state.time*1.55)>-.2;lasers.forEach(m=>{m.visible=laserOn;if(laserOn&&Math.abs(cat.position.x-m.position.x)<.17&&Math.abs(cat.position.z+.2)<1.06)seen=true});state.alert=Math.max(0,Math.min(100,state.alert+dt*(seen?(keys.ShiftLeft?19:31)*mult:-13)));state.peak=Math.max(state.peak,state.alert);if(state.alert>=100)finish(false);treasures.forEach(m=>{if(m.visible&&m.position.distanceTo(cat.position)<.78){m.visible=false;state.loot++;sync();say('额外战利品 +300 分。真是只识货的小猫。');beep(1100,.14)}});if(state.gem&&Math.hypot(cat.position.x,cat.position.z-5.05)<.65)finish(true);
const targets=[[-5,4.2,!state.card],[5,4.2,!state.power],[0,-2.7,!state.gem],[0,5.05,state.gem]];interactBtn.hidden=!targets.some(([x,z,on])=>on&&Math.hypot(cat.position.x-x,cat.position.z-z)<1.6);if(performance.now()>toastUntil){$('#toast').textContent=interactBtn.hidden?(state.alert>20?'你正在暴露！躲到展台后，或按 1 使用烟雾弹。':state.gem?'返回绿色入口，把月光带回家。':'保持安静。观察巡逻，再迈出下一步。'):'目标就在附近 · 按 E 或点击「交互」'}
}else{interactBtn.hidden=true;guards.forEach(g=>g.cone.visible=state.vision);lasers.forEach(m=>m.visible=!state.power)}
smokeMesh.visible=state.phase==='run'&&state.time<state.smokeUntil;smokeMesh.position.copy(cat.position).setY(.55);mouse.visible=state.time<state.decoyUntil;$('#timer').textContent=`${String(Math.floor(state.time/60)).padStart(2,'0')}:${String(Math.floor(state.time%60)).padStart(2,'0')}`;$('#alert-fill').style.width=state.alert+'%';$('#alert-number').textContent=Math.round(state.alert)+'%';$('#alert-label').textContent=state.alert>30?'正在被发现':'暴露程度';$('#status').textContent=state.phase==='run'?(state.time<state.smokeUntil?'烟雾掩护生效中':state.power?'安保已关闭 · 展柜已解锁':'安保在线 · 注意激光节奏'):'所有系统暂停 · 自由规划';renderer.render(scene,camera)}sync();resize();requestAnimationFrame(tick);try{const best=localStorage.getItem('midnight-paws-best');if(best)$('#best').textContent=`个人最佳行动评分：${best} 分`}catch{}
if(document.modelContext?.registerTool){document.modelContext.registerTool({name:'read_heist_state',description:'Read the current museum heist status and route.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:(input)=>{if(!input||typeof input!=='object'||Object.keys(input).length)throw new Error('Expected an empty object');return {...state,position:{x:cat.position.x,z:cat.position.z},path}}});}
